from pathlib import Path

file_path = inputs.get('File', '')
if not file_path:
    raise Exception('No File provided')
file_path = file_path.replace('.####', '')

print(f"File path type: {type(file_path)}, File path value: {file_path}")
comments = inputs.get('Comments', '')
status = inputs.get('Status') or 'Work in Progress'

slack = core.getPlugin('Slack')
if not slack:
    raise Exception('Slack plugin not loaded')

project = slack.get_current_project()

versioninfo_str = f"{slack.get_version_folder(file_path)}/versioninfo.json".replace('\\', '/')
versioninfo = Path(versioninfo_str)

state_data = {'state_type': 'execution_graph', 'ui': 'EG', 'app': 'Standalone', 'project': project, 'comments': comments, 'versioninfo': versioninfo}

if slack.get_server_approvals():
    state_data['status'] = status
else:
    state_data['status'] = None

try:
    slack.publish_to_slack(file_path, state_data)
    Result = {'success': True, 'message': 'Successfully published to Slack', 'file': file_path, 'state_data': state_data}
except Exception as e:
    Result = {'success': False, 'message': f"Failed to publish to Slack: {str(e)}", 'file': file_path, 'state_data': state_data}
